//! Source-event timestamps are assigned locally, never generated by Luna.
use crate::model::{ContextTiming, CurrentState, EventKind, Summary, TurnEvent};
use crate::transcript::TranscriptExcerpt;

pub fn resolve(
    current: &CurrentState,
    summary: &Summary,
    events: &[TurnEvent],
    history: Option<&TranscriptExcerpt>,
) -> ContextTiming {
    let history_times = history
        .into_iter()
        .flat_map(|h| &h.messages)
        .filter(|m| !m.previous_session)
        .filter_map(|m| m.recorded_at_unix);
    let latest = events
        .iter()
        .map(|e| e.recorded_at_unix)
        .filter(|at| *at > 0)
        .chain(history_times)
        .max();
    let mut timing = ContextTiming {
        through_unix: latest.or(current.timing.through_unix),
        partial_history: history.map_or(current.timing.partial_history, |h| h.truncated),
        ..ContextTiming::default()
    };
    for decision in &summary.decisions {
        let previous = current.summary.decisions.iter().find(|old| {
            old.id == decision.id
                && old.status == decision.status
                && (old.text == decision.text
                    || (history.is_none()
                        && !old.evidence.is_empty()
                        && old.evidence == decision.evidence))
        });
        let kept = previous.and_then(|old| current.timing.decisions.get(&old.id).copied());
        let at = if kept.is_some() || (previous.is_some() && history.is_none()) {
            kept
        } else {
            None.or_else(|| {
                evidence_time(
                    &decision.evidence,
                    events,
                    history,
                    Some(
                        &if decision.status == crate::model::DecisionStatus::Proposed {
                            EventKind::AssistantFinal
                        } else {
                            EventKind::UserPrompt
                        },
                    ),
                )
            })
            .or_else(|| evidence_time(&decision.evidence, events, history, None))
        };
        if let Some(at) = at {
            timing.decisions.insert(decision.id.clone(), at);
        }
    }
    for item in &summary.progress {
        let previous = current.summary.progress.iter().find(|old| {
            old.status == item.status
                && (old.text == item.text
                    || (history.is_none()
                        && !old.evidence.is_empty()
                        && old.evidence == item.evidence))
        });
        let kept = previous.and_then(|old| current.timing.progress.get(&old.text).copied());
        let at = if kept.is_some() || (previous.is_some() && history.is_none()) {
            kept
        } else {
            None.or_else(|| {
                evidence_time(
                    &item.evidence,
                    events,
                    history,
                    Some(&EventKind::AssistantFinal),
                )
            })
            .or_else(|| evidence_time(&item.evidence, events, history, None))
        };
        if let Some(at) = at {
            timing.progress.insert(item.text.clone(), at);
        }
    }
    resolve_followups(current, summary, events, history, &mut timing);
    timing
}

fn resolve_followups(
    current: &CurrentState,
    summary: &Summary,
    events: &[TurnEvent],
    history: Option<&TranscriptExcerpt>,
    timing: &mut ContextTiming,
) {
    for blocker in &summary.blockers {
        let previous = current
            .summary
            .blockers
            .iter()
            .find(|old| old.text() == blocker.text() && old.priority() == blocker.priority());
        let kept = previous.and_then(|old| current.timing.blockers.get(old.text()).copied());
        let at = if kept.is_some() || (previous.is_some() && history.is_none()) {
            kept
        } else {
            evidence_time(blocker.evidence(), events, history, None)
        };
        if let Some(at) = at {
            timing.blockers.insert(blocker.text().to_string(), at);
        }
    }
    for action in &summary.next_actions {
        let previous = current.summary.next_actions.iter().find(|old| {
            old.text == action.text
                && old.owner == action.owner
                && old.step == action.step
                && old.when == action.when
        });
        let kept = previous.and_then(|old| current.timing.next_actions.get(&old.text).copied());
        let at = if kept.is_some() || (previous.is_some() && history.is_none()) {
            kept
        } else {
            evidence_time(&action.evidence, events, history, None)
        };
        if let Some(at) = at {
            timing.next_actions.insert(action.text.clone(), at);
        }
    }
}

fn evidence_time(
    evidence: &[String],
    events: &[TurnEvent],
    history: Option<&TranscriptExcerpt>,
    preferred: Option<&EventKind>,
) -> Option<u64> {
    evidence
        .iter()
        .filter_map(|reference| {
            if let Some(seq) = reference
                .strip_prefix("event:")
                .and_then(|n| n.parse::<u64>().ok())
            {
                return events
                    .iter()
                    .find(|e| e.seq == seq && preferred.is_none_or(|kind| kind == &e.kind))
                    .map(|e| e.recorded_at_unix)
                    .filter(|at| *at > 0);
            }
            history?
                .messages
                .iter()
                .find(|m| {
                    m.evidence == *reference
                        && match preferred {
                            Some(EventKind::UserPrompt) => m.role == "user",
                            Some(EventKind::AssistantFinal) => m.role == "assistant",
                            Some(EventKind::Interrupted) => false,
                            None => true,
                        }
                })?
                .recorded_at_unix
        })
        .max()
}

/// Korean local time (UTC+9). Dates from another year include the year.
pub fn format_kst(timestamp: u64, now: u64) -> String {
    let Some((year, month, day, hour, minute)) = kst_parts(timestamp) else {
        return crate::tr!("시각 미기록", "Time not recorded").into();
    };
    if kst_parts(now).is_some_and(|current| current.0 == year) {
        format!("{month}/{day} {hour:02}:{minute:02}")
    } else {
        format!("{year}/{month}/{day} {hour:02}:{minute:02}")
    }
}

fn kst_parts(timestamp: u64) -> Option<(u64, u64, u64, u64, u64)> {
    let local = timestamp.checked_add(9 * 3600)?;
    let mut days = local / 86_400;
    let mut year = 1970;
    let leap = |year: u64| {
        year.is_multiple_of(4) && (!year.is_multiple_of(100) || year.is_multiple_of(400))
    };
    while year <= 9999 {
        let length = if leap(year) { 366 } else { 365 };
        if days < length {
            break;
        }
        days -= length;
        year += 1;
    }
    if year > 9999 {
        return None;
    }
    let months = [
        31,
        if leap(year) { 29 } else { 28 },
        31,
        30,
        31,
        30,
        31,
        31,
        30,
        31,
        30,
        31,
    ];
    let mut month = 1;
    for length in months {
        if days < length {
            break;
        }
        days -= length;
        month += 1;
    }
    Some((
        year,
        month,
        days + 1,
        local % 86_400 / 3600,
        local % 3600 / 60,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Decision, DecisionStatus, ProgressItem, ProgressStatus};
    use crate::transcript::{TranscriptMessage, utc_timestamp_seconds};

    fn summary() -> Summary {
        Summary {
            decisions: vec![Decision {
                id: "D-001".into(),
                text: "계획 승인".into(),
                status: DecisionStatus::Active,
                supersedes: None,
                evidence: vec!["history:1".into()],
            }],
            progress: vec![ProgressItem {
                text: "PR 생성".into(),
                status: ProgressStatus::Reported,
                evidence: vec!["history:2".into()],
            }],
            ..Summary::default()
        }
    }

    #[test]
    fn records_source_times_and_keeps_them_when_resummarized() {
        let summary = summary();
        let history = TranscriptExcerpt {
            truncated: false,
            messages: vec![
                TranscriptMessage {
                    evidence: "history:1".into(),
                    role: "user".into(),
                    content: "계획 승인".into(),
                    previous_session: false,
                    unfinished_turn: false,
                    recorded_at_unix: Some(100),
                },
                TranscriptMessage {
                    evidence: "history:2".into(),
                    role: "assistant".into(),
                    content: "PR 생성".into(),
                    previous_session: false,
                    unfinished_turn: false,
                    recorded_at_unix: Some(200),
                },
            ],
        };
        let first = resolve(&CurrentState::default(), &summary, &[], Some(&history));
        assert_eq!(first.through_unix, Some(200));
        assert_eq!(first.decisions["D-001"], 100);
        assert_eq!(first.progress["PR 생성"], 200);
        let current = CurrentState {
            summary: summary.clone(),
            timing: first.clone(),
            updated_at_unix: Some(99999),
            ..CurrentState::default()
        };
        let second = resolve(&current, &summary, &[], None);
        assert_eq!(first, second);
    }

    #[test]
    fn unknown_legacy_times_are_not_replaced_by_summary_creation_time() {
        let summary = summary();
        let current = CurrentState {
            summary: summary.clone(),
            updated_at_unix: Some(99999),
            ..CurrentState::default()
        };
        let timing = resolve(&current, &summary, &[], None);
        assert_eq!(timing.through_unix, None);
        assert!(timing.decisions.is_empty());
        assert!(timing.progress.is_empty());
    }

    #[test]
    fn paraphrases_keep_time_but_status_changes_use_new_report_time() {
        let mut previous = summary();
        previous.progress[0].evidence = vec!["event:1".into()];
        let current = CurrentState {
            summary: previous.clone(),
            timing: ContextTiming {
                progress: [("PR 생성".into(), 100)].into(),
                ..ContextTiming::default()
            },
            ..CurrentState::default()
        };
        let mut reworded = previous;
        reworded.progress[0].text = "문서 PR 생성".into();
        let same = resolve(&current, &reworded, &[], None);
        assert_eq!(same.progress["문서 PR 생성"], 100);
        reworded.progress[0].status = ProgressStatus::Done;
        reworded.progress[0].evidence.push("event:2".into());
        let report = TurnEvent {
            seq: 2,
            kind: EventKind::AssistantFinal,
            session_id: "session".into(),
            turn_id: None,
            model: None,
            content: "검증 완료".into(),
            truncated: false,
            recorded_at_unix: 300,
            cwd: "/repo".into(),
        };
        let changed = resolve(&current, &reworded, &[report], None);
        assert_eq!(changed.progress["문서 PR 생성"], 300);
        assert_eq!(changed.through_unix, Some(300));
    }

    #[test]
    fn followup_times_survive_refresh_and_change_with_stage() {
        let summary: Summary = serde_json::from_value(serde_json::json!({
            "blockers":[{"text":"승인 필요","priority":"user_decision","evidence":["event:1"]}],
            "next_actions":[{"owner":"sol","text":"구현","evidence":["event:1"],"step":1,"when":"승인 후"}]
        })).unwrap();
        let event = TurnEvent {
            seq: 1,
            kind: EventKind::AssistantFinal,
            session_id: "session".into(),
            turn_id: None,
            model: None,
            content: "승인 대기".into(),
            truncated: false,
            recorded_at_unix: 100,
            cwd: "/repo".into(),
        };
        let timing = resolve(
            &CurrentState::default(),
            &summary,
            std::slice::from_ref(&event),
            None,
        );
        assert_eq!(timing.blockers["승인 필요"], 100);
        assert_eq!(timing.next_actions["구현"], 100);
        let current = CurrentState {
            summary: summary.clone(),
            timing: timing.clone(),
            ..CurrentState::default()
        };
        assert_eq!(resolve(&current, &summary, &[], None), timing);
        let mut updated = summary;
        updated.blockers.clear();
        updated.next_actions[0].step = Some(0);
        updated.next_actions[0].when = Some("지금".into());
        updated.next_actions[0].evidence = vec!["event:2".into()];
        let approval = TurnEvent {
            seq: 2,
            kind: EventKind::UserPrompt,
            recorded_at_unix: 300,
            ..event
        };
        let changed = resolve(&current, &updated, &[approval], None);
        assert!(changed.blockers.is_empty());
        assert_eq!(changed.next_actions["구현"], 300);
        let empty = resolve(&current, &Summary::default(), &[], None);
        assert!(empty.blockers.is_empty());
        assert!(empty.next_actions.is_empty());
    }

    #[test]
    fn formats_korean_midnight_leap_day_and_previous_year() {
        let now = utc_timestamp_seconds("2026-09-06T00:00:00Z").unwrap();
        let at = |s| utc_timestamp_seconds(s).unwrap();
        assert_eq!(format_kst(at("2026-09-05T15:12:00Z"), now), "9/6 00:12");
        assert_eq!(
            format_kst(at("2024-02-28T15:00:00Z"), now),
            "2024/2/29 00:00"
        );
        assert_eq!(format_kst(at("2025-12-31T15:00:00Z"), now), "1/1 00:00");
        assert_eq!(
            format_kst(u64::MAX, now),
            crate::tr!("시각 미기록", "Time not recorded")
        );
    }
}
